<script setup lang="ts">
import { computed, defineComponent, h, ref, watch } from 'vue'
import { ArrowLeft, Connection, Delete, Edit, Plus, Refresh } from '@element-plus/icons-vue'
import InlineKnowledgeEditor from './InlineKnowledgeEditor.vue'
import DocumentAssets from './DocumentAssets.vue'

const props = withDefaults(defineProps<{
  centerTitle: string
  centerKey: string
  record: Record<string, any> | null
  loading?: boolean
  error?: string
  canManage?: boolean
  showPrice?: boolean
  canDownload?: boolean
  startEditing?: boolean
}>(), { loading:false, error:'', canManage:false, showPrice:false, canDownload:false, startEditing:false })
const emit = defineEmits<{ back:[]; edit:[]; save:[value:any]; delete:[]; relate:[]; editBom:[]; retry:[]; openRelation:[relation:any] }>()
const activeTab = ref('overview')
const editing = ref(false)
const beginEdit=()=>{editing.value=true}
const cancelEdit=()=>{editing.value=false}
const saveInline=(value:any)=>{emit('save',value);editing.value=false}
const statusLabel = (value?:string) => ({SUPPORTED:'正式支持',ON_SALE:'在售',OFF_SALE:'停售',ACTIVE:'启用',PUBLISHED:'已发布',DRAFT:'草稿',BETA:'Beta',DISABLED:'停用',PLANNING:'规划中'} as Record<string,string>)[value||''] || '状态待确认'
const typeLabel = (value?:string) => ({PLATFORM:'平台软件',CLIENT:'客户端软件',SERVICE:'服务组件',PRIVATE:'私有化部署',CLOUD:'云端部署',HYBRID:'混合部署',DETECTION:'目标检测',OCR:'文字识别',CLASSIFICATION:'分类',SEGMENTATION:'分割',TRACKING:'跟踪',TIME_SERIES:'时序分析',DATA_MODEL:'数据模型',MULTIMODAL:'多模态',FUSION:'融合',STANDARD:'标准型',ENHANCED:'增强型',FLAGSHIP:'旗舰型'} as Record<string,string>)[value||''] || value || '-'
const relationGroups = computed(() => Object.fromEntries(['products','software','algorithms','model-capabilities','scenes','solutions'].map((type) => [type,(props.record?.relations||[]).filter((item:any) => item.type===type)])))
const highlightedMetrics = computed(() => (props.record?.metrics||[]).filter((item:any) => item.highlight).slice(0,4))
const evidenceMetric = computed(() => highlightedMetrics.value[0] || props.record?.metrics?.[0] || null)
const softwareShot = computed(() => props.record?.screenshots?.[0]?.image || props.record?.logo || '/assets/solution-overview.png')
const sceneImage = computed(() => {
  const image = props.record?.coverImage || ''
  const isUiMockup = /\/(?:product-(?:terminal|radar)|scene-waterway)\.png(?:\?|$)/i.test(image)
  return image && !isUiMockup ? image : '/assets/bridge-ship-waterway.jpg'
})
const tabs = computed(() => {
  if(props.centerKey==='software') return [['overview','软件概览'],['functions','系统功能'],['versions','版本信息'],['deployment','部署要求'],['commercial','物料与商务'],['relations','设备/算法/模型/场景'],['boundaries','能力边界'],['screenshots','软件截图'],['documents','相关资料']]
  if(props.centerKey==='algorithms') return [['overview','算法概览'],['principle','算法原理'],['input','输入数据'],['output','输出结果'],['parameters','核心参数'],['metrics','性能指标'],['commercial','授权与商务'],['relations','关联知识'],['boundaries','能力边界'],['documents','相关资料']]
  if(props.centerKey==='model-capabilities') return [['overview','模型概览'],['metrics','性能指标'],['input','输入要求'],['output','输出定义'],['deployment','部署规格'],['relations','硬件/算法/软件/场景'],['boundaries','能力边界'],['documents','相关资料']]
  if(props.centerKey==='scenes') return [['overview','场景概览'],['pains','业务痛点'],['goals','建设目标'],['conditions','关键条件'],['matrix','能力矩阵'],['process','业务流程'],['products','推荐产品'],['solutions','标准方案'],['documents','相关资料']]
  return [['overview','方案概览'],['conditions','适用条件'],['architecture','系统架构'],['composition','系统组成'],['coverage','能力覆盖'],['bom','标准BOM'],['documents','相关资料']]
})
const relationLabel = (type:string) => ({products:'产品',software:'软件',algorithms:'算法','model-capabilities':'模型能力',scenes:'场景',solutions:'方案'} as Record<string,string>)[type] || type
const requirementLabel = (value?:string) => ({REQUIRED:'必需',RECOMMENDED:'推荐',OPTIONAL:'可选',CORE:'核心'} as Record<string,string>)[value||''] || '推荐'
const coverageLabel = (value?:string) => ({COVERED:'已覆盖',OPTIONAL:'可选',NOT_COVERED:'未覆盖'} as Record<string,string>)[value||''] || value || '-'
const layerOrder = ['感知层','边缘智能层','平台层','业务应用层']
const architectureGroups = computed(() => layerOrder.map((layer) => ({layer,items:(props.record?.architecture||[]).filter((item:any) => item.layer===layer)})).filter((group) => group.items.length))
watch(() => props.record?.id, () => { activeTab.value='overview';editing.value=props.startEditing })
watch(() => props.startEditing, (value) => {if(value)editing.value=true})
const BoundaryItems = defineComponent({props:{items:{type:Array,default:()=>[]}},setup(boundaryProps){return()=>h('div',{class:'boundary-items'},(boundaryProps.items as string[]).map((item,index)=>h('article',[h('span',String(index+1)),h('p',item)])))}})
const RelationPanel = defineComponent({props:{groups:{type:Object,required:true},canManage:Boolean},emits:['open','relate'],setup(panelProps,{emit:panelEmit}){const labels:any={products:'产品',software:'软件',algorithms:'算法','model-capabilities':'模型能力',scenes:'场景',solutions:'方案'};return()=>h('section',{class:'content-section relation-panel'},[h('div',{class:'section-head'},[h('div',[h('h2','关联知识'),h('p','统一关系底座双向读取。')]),panelProps.canManage?h('button',{class:'native-action',onClick:()=>panelEmit('relate')},'维护关系'):null]),h('div',{class:'relation-panel-grid'},Object.entries(panelProps.groups as any).flatMap(([type,items]:any)=>(items as any[]).map((item:any)=>h('button',{onClick:()=>panelEmit('open',item)},[h('small',labels[type]||type),h('strong',item.name),h('span',item.meta?.purpose||item.summary||'查看详情')]))))])}})
</script>

<template>
  <section class="center-detail" v-loading="loading">
    <div class="detail-nav"><el-button link :icon="ArrowLeft" @click="emit('back')">{{ centerTitle }} / {{ record?.name || '详情' }}</el-button></div>
    <el-alert v-if="error" type="error" :title="error" :closable="false" show-icon><el-button :icon="Refresh" @click="emit('retry')">重新加载</el-button></el-alert>

    <template v-else-if="record">
      <header v-if="centerKey==='software'" class="hero software-hero"><div class="software-visual"><img :src="softwareShot" :alt="record.name"></div><div class="hero-copy"><div class="eyebrow">{{ typeLabel(record.softwareType) }} / {{ typeLabel(record.deploymentMode) }}</div><h1>{{ record.name }}</h1><div class="identity"><strong>{{ record.code }}</strong><span>{{ record.version }}</span><el-tag type="success" effect="plain">{{ statusLabel(record.status) }}</el-tag></div><p>{{ record.summary }}</p><div class="hero-metrics"><div><strong>{{ record.modules?.length||0 }}</strong><span>功能模块</span></div><div><strong>{{ relationGroups.products?.length||0 }}</strong><span>支持设备</span></div><div><strong>{{ relationGroups['model-capabilities']?.length||0 }}</strong><span>支持模型</span></div><div><strong>{{ typeLabel(record.deploymentMode) }}</strong><span>部署方式</span></div></div></div><div class="hero-actions"><el-button v-if="canManage" type="primary" :icon="Edit" @click="emit('edit')">编辑软件</el-button><el-button @click="activeTab='versions'">查看版本记录</el-button><div class="release-facts"><span>当前版本 <b>{{ record.version }}</b></span><span>最近更新 <b>{{ record.updatedAt?.slice(0,10) }}</b></span><span>运行环境 <b>{{ record.supportedOs?.join(' / ')||'待确认' }}</b></span></div><el-button v-if="canManage" text type="danger" :icon="Delete" @click="emit('delete')">删除软件</el-button></div></header>

      <header v-else-if="centerKey==='algorithms'" class="hero algorithm-hero"><div class="hero-copy"><div class="eyebrow">{{ record.category }}算法</div><h1>{{ record.name }}</h1><div class="identity"><strong>{{ record.code }}</strong><span>{{ record.version }}</span><el-tag type="success" effect="plain">{{ statusLabel(record.status) }}</el-tag></div><p>{{ record.summary }}</p></div><div class="metric-hero"><div v-for="item in highlightedMetrics" :key="item.id"><strong>{{ item.value }}{{ item.unit }}</strong><span>{{ item.name }}</span></div><div v-if="!highlightedMetrics.length"><strong>待验证</strong><span>性能指标</span></div></div><div class="hero-actions compact"><el-button v-if="canManage" type="primary" :icon="Edit" @click="emit('edit')">编辑算法</el-button><el-button :icon="Connection" @click="activeTab='relations'">查看关系</el-button><el-button v-if="canManage" text type="danger" :icon="Delete" @click="emit('delete')">删除</el-button></div></header>

      <header v-else-if="centerKey==='model-capabilities'" class="hero model-hero"><div class="model-symbol">{{ record.category || 'AI' }}</div><div class="hero-copy"><div class="eyebrow">{{ typeLabel(record.modelType) }} / {{ record.taskType || record.functionType }}</div><h1>{{ record.name }}</h1><div class="identity"><strong>{{ record.code }}</strong><span>{{ record.version }}</span><el-tag type="success" effect="plain">{{ statusLabel(record.status) }}</el-tag></div><p>{{ record.summary }}</p></div><div class="metric-hero"><div v-for="item in highlightedMetrics" :key="item.id"><strong>{{ item.value }}{{ item.unit }}</strong><span>{{ item.name }}</span><small>{{ item.condition || '测试条件待补充' }}</small></div><div v-if="!highlightedMetrics.length"><strong>待验证</strong><span>核心性能</span></div></div><div class="hero-actions compact"><el-button v-if="canManage" type="primary" :icon="Edit" @click="emit('edit')">编辑模型</el-button><el-button @click="activeTab='metrics'">查看评测依据</el-button><el-button v-if="canManage" text type="danger" :icon="Delete" @click="emit('delete')">删除</el-button></div></header>

      <header v-else-if="centerKey==='scenes'" class="scene-hero" :style="{backgroundImage:`linear-gradient(90deg,rgba(10,31,50,.88),rgba(10,31,50,.14)),url(${sceneImage})`}"><div class="hero-copy"><div class="eyebrow">{{ record.category }} / {{ record.tags?.join(' · ') }}</div><h1>{{ record.name }}</h1><p>{{ record.summary }}</p><div class="scene-stats"><strong>核心能力 {{ relationGroups['model-capabilities']?.length||0 }} 项</strong><strong>推荐产品 {{ relationGroups.products?.length||0 }} 个</strong><strong>标准方案 {{ relationGroups.solutions?.length||0 }} 套</strong></div></div><div class="hero-actions compact"><el-button v-if="canManage" type="primary" :icon="Edit" @click="emit('edit')">编辑场景</el-button><el-button v-if="canManage" text type="danger" :icon="Delete" @click="emit('delete')">删除</el-button></div></header>

      <header v-else class="hero solution-hero"><div class="solution-visual"><img :src="record.coverImage||'/assets/solution-overview.png'" :alt="record.name"></div><div class="hero-copy"><div class="eyebrow">{{ record.scene }} / {{ typeLabel(record.tier) }}</div><h1>{{ record.name }}</h1><div class="identity"><strong>{{ record.code }}</strong><span>{{ typeLabel(record.tier) }}</span><el-tag type="success" effect="plain">{{ statusLabel(record.status) }}</el-tag></div><p>{{ record.summary }}</p><div class="hero-metrics"><div><strong>{{ record.coverageScope || '范围待确认' }}</strong><span>适用范围</span></div><div><strong>{{ record.capabilityCoverage?.length||0 }} 项</strong><span>能力覆盖</span></div><div><strong>{{ record.bom?.items?.length||0 }} 类</strong><span>标准配置</span></div></div></div><div class="hero-actions"><el-button v-if="canManage" type="primary" :icon="Edit" @click="emit('edit')">编辑方案</el-button><div v-if="showPrice" class="price-panel"><span>产品参考总价</span><strong>{{ record.bom?.currency==='CNY'?'¥':'' }} {{ Number(record.bom?.productReferenceTotal||0).toLocaleString() }}</strong><small>仅 PRICE_VIEW 可见</small></div><el-button v-if="canManage" text type="danger" :icon="Delete" @click="emit('delete')">删除方案</el-button></div></header>

      <nav class="detail-tabs"><button v-for="tab in tabs" :key="tab[0]" :class="{active:activeTab===tab[0]}" @click="activeTab=tab[0]">{{ tab[1] }}</button></nav>
      <InlineKnowledgeEditor v-if="editing&&!['relations','documents','products','solutions'].includes(activeTab)" :center-key="centerKey" :record="record" :active-tab="activeTab" :show-price="showPrice" @save="saveInline" @cancel="cancelEdit"/>
      <div v-else-if="editing" class="edit-banner"><span>关系与资料使用本板块专用维护控件。</span><el-button @click="cancelEdit">退出编辑</el-button></div>

      <main v-show="!editing||['relations','documents','products','solutions'].includes(activeTab)" class="detail-content">
        <template v-if="centerKey==='software'">
          <section v-if="activeTab==='overview' || activeTab==='functions'" class="content-section"><div class="section-head"><div><h2>系统功能</h2><p>模块与子功能为软件技术资产的正式事实源。</p></div><span>{{ record.modules?.length||0 }} 模块 · {{ record.modules?.reduce((n:number,m:any)=>n+(m.features?.length||0),0)||0 }} 功能</span></div><div class="module-matrix"><article v-for="(module,index) in record.modules" :key="module.id||module.name"><span>{{ String(index+1).padStart(2,'0') }}</span><div><h3>{{ module.name }}</h3><p>{{ module.description }}</p><ul><li v-for="feature in module.features" :key="feature.id||feature.name">{{ feature.name }}<small>{{ feature.description }}</small></li></ul></div></article></div><el-empty v-if="!record.modules?.length" description="暂无功能模块"/></section>
          <section v-if="activeTab==='overview'" class="relation-band"><article v-for="type in ['products','algorithms','model-capabilities','scenes']" :key="type"><h3>{{ relationLabel(type) }}</h3><button v-for="relation in relationGroups[type]" :key="relation.id" @click="emit('openRelation',relation)">{{ relation.name }}</button><span v-if="!relationGroups[type]?.length">暂无关联</span></article></section>
          <RelationPanel v-else-if="activeTab==='relations'" :groups="relationGroups" :can-manage="canManage" @open="emit('openRelation',$event)" @relate="emit('relate')"/>
          <section v-if="activeTab==='versions'" class="content-section"><div class="section-head"><div><h2>版本信息</h2><p>轻量版本历史，不替代软件制品发布系统。</p></div></div><el-timeline><el-timeline-item v-for="item in record.versions" :key="item.id||item.version" :timestamp="item.releasedAt?.slice(0,10)||'日期待确认'" placement="top"><b>{{ item.version }}</b><p>{{ item.summary }}</p></el-timeline-item></el-timeline></section>
          <section v-if="activeTab==='deployment'" class="content-section"><div class="section-head"><div><h2>部署要求</h2><p>运行环境、数据库与协议支持。</p></div></div><div class="fact-grid"><div><span>部署方式</span><strong>{{ typeLabel(record.deploymentMode) }}</strong></div><div><span>操作系统</span><strong>{{ record.supportedOs?.join(' / ')||'-' }}</strong></div><div><span>数据库</span><strong>{{ record.databases?.join(' / ')||'-' }}</strong></div><div><span>支持协议</span><strong>{{ record.protocols?.join(' / ')||'-' }}</strong></div></div></section>
          <section v-if="activeTab==='boundaries'" class="content-section"><BoundaryItems :items="record.boundaries"/></section>
          <section v-if="activeTab==='screenshots'" class="content-section"><div class="screenshot-grid"><figure v-for="item in record.screenshots" :key="item.id||item.image"><img :src="item.image" :alt="item.title"><figcaption>{{ item.title||'软件界面' }}</figcaption></figure></div><el-empty v-if="!record.screenshots?.length" description="暂无软件截图"/></section>
        </template>

        <template v-else-if="centerKey==='algorithms'">
          <section v-if="activeTab==='overview'" class="algorithm-pipeline"><article><small>INPUT</small><h2>输入数据</h2><p>{{ record.inputSummary||'输入定义待完善' }}</p></article><span>→</span><article class="process"><small>PROCESS</small><h2>{{ record.name }}核心处理</h2><p>{{ record.principle||'算法原理待完善' }}</p></article><span>→</span><article><small>OUTPUT</small><h2>输出结果</h2><p>{{ record.outputSummary||'输出定义待完善' }}</p></article></section>
          <section v-if="activeTab==='overview' || activeTab==='parameters' || activeTab==='metrics'" class="dual-panels"><article v-if="activeTab!=='metrics'"><h2>核心参数 · 用于配置</h2><div class="metric-grid"><div v-for="item in record.parameters" :key="item.id"><span>{{ item.name }}</span><strong>{{ item.value }}{{ item.unit }}</strong></div></div><el-empty v-if="!record.parameters?.length" description="暂无核心参数"/></article><article v-if="activeTab!=='parameters'"><h2>性能指标 · 测试结果</h2><el-table :data="record.metrics||[]"><el-table-column prop="name" label="指标"/><el-table-column label="数值"><template #default="scope"><b>{{ scope.row.value }}{{ scope.row.unit }}</b></template></el-table-column><el-table-column prop="condition" label="测试条件"/><el-table-column prop="source" label="来源"/></el-table></article></section>
          <section v-if="activeTab==='principle' || activeTab==='input' || activeTab==='output'" class="content-section"><div class="section-head"><div><h2>{{ activeTab==='principle'?'算法原理':activeTab==='input'?'输入数据':'输出结果' }}</h2></div></div><p class="long-copy">{{ activeTab==='principle'?record.principle:activeTab==='input'?record.inputSummary:record.outputSummary }}</p></section>
          <RelationPanel v-if="activeTab==='relations'" :groups="relationGroups" :can-manage="canManage" @open="emit('openRelation',$event)" @relate="emit('relate')"/>
          <section v-if="activeTab==='boundaries'" class="content-section"><BoundaryItems :items="record.boundaries"/></section>
        </template>

        <template v-else-if="centerKey==='model-capabilities'">
          <section v-if="activeTab==='overview' || activeTab==='metrics'" class="content-section"><div class="section-head"><div><h2>性能指标测试依据</h2><p>指标值与测试条件、数据来源同时展示。</p></div><span>{{ evidenceMetric?.condition||'测试条件待补充' }}</span></div><div v-if="evidenceMetric" class="evidence-strip"><div><span>数据集</span><strong>{{ evidenceMetric.dataset||'待补充' }}</strong></div><div><span>样本量</span><strong>{{ evidenceMetric.sampleCount ? Number(evidenceMetric.sampleCount).toLocaleString() : '待补充' }}</strong></div><div><span>输入分辨率</span><strong>{{ evidenceMetric.inputResolution||'待补充' }}</strong></div><div><span>测试硬件</span><strong>{{ evidenceMetric.hardware||'待补充' }}</strong></div><div><span>Runtime</span><strong>{{ evidenceMetric.runtime||'待补充' }}</strong></div><div><span>测试日期</span><strong>{{ evidenceMetric.testedAt?.slice(0,10)||'待补充' }}</strong></div><div><span>数据来源</span><strong>{{ evidenceMetric.source||'待补充' }}</strong></div></div><el-table v-if="activeTab==='metrics'" :data="record.metrics||[]"><el-table-column prop="name" label="指标"/><el-table-column label="数值"><template #default="scope"><b>{{ scope.row.value }}{{ scope.row.unit }}</b></template></el-table-column><el-table-column prop="condition" label="测试条件"/><el-table-column prop="source" label="来源"/></el-table></section>
          <section v-if="activeTab==='overview' || activeTab==='input' || activeTab==='output'" class="io-grid"><article v-if="activeTab!=='output'"><h2>输入要求</h2><el-table :data="record.inputDefinitions||[]"><el-table-column prop="name" label="字段"/><el-table-column prop="dataType" label="类型"/><el-table-column label="必填"><template #default="scope">{{ scope.row.required?'是':'否' }}</template></el-table-column><el-table-column label="说明 / 示例"><template #default="scope">{{ scope.row.description }} · {{ scope.row.example }}</template></el-table-column></el-table></article><article v-if="activeTab!=='input'"><h2>输出定义</h2><el-table :data="record.outputDefinitions||[]"><el-table-column prop="name" label="字段"/><el-table-column prop="dataType" label="类型"/><el-table-column label="说明 / 示例"><template #default="scope">{{ scope.row.description }} · {{ scope.row.example }}</template></el-table-column></el-table></article></section>
          <section v-if="activeTab==='overview' || activeTab==='deployment'" class="deployment-band"><h2>部署规格</h2><div><span v-for="(value,key) in record.deploymentRequirements" :key="key"><small>{{ key }}</small><strong>{{ value }}</strong></span></div></section>
          <RelationPanel v-if="activeTab==='relations'" :groups="relationGroups" :can-manage="canManage" @open="emit('openRelation',$event)" @relate="emit('relate')"/>
          <section v-if="activeTab==='boundaries'" class="content-section"><BoundaryItems :items="record.boundaries"/></section>
        </template>

        <template v-else-if="centerKey==='scenes'">
          <div v-if="activeTab==='overview' || activeTab==='pains' || activeTab==='goals'" class="dual-panels"><article v-if="activeTab!=='goals'"><h2>业务痛点</h2><div class="statement-grid"><div v-for="(item,index) in record.painPoints" :key="item.id||item.title"><span>{{ String(index+1).padStart(2,'0') }}</span><strong>{{ item.title }}</strong><p>{{ item.description }}</p></div></div></article><article v-if="activeTab!=='pains'"><h2>建设目标</h2><div class="statement-grid"><div v-for="(item,index) in record.goals" :key="item.id||item.title"><span>{{ String(index+1).padStart(2,'0') }}</span><strong>{{ item.title }}</strong><p>{{ item.description }}</p></div></div></article></div>
          <section v-if="activeTab==='conditions'" class="content-section"><div class="condition-list"><span v-for="item in record.conditions" :key="item">{{ item }}</span></div><el-empty v-if="!record.conditions?.length" description="关键条件待完善"/></section>
          <section v-if="activeTab==='overview' || activeTab==='matrix'" class="content-section"><div class="section-head"><div><h2>模型能力需求矩阵</h2><p>从真实模型能力关系和关系属性读取。</p></div></div><el-table :data="relationGroups['model-capabilities']||[]"><el-table-column prop="name" label="能力 / 模型"/><el-table-column label="业务说明"><template #default="scope">{{ scope.row.meta?.purpose||scope.row.summary||'-' }}</template></el-table-column><el-table-column label="需求等级"><template #default="scope"><el-tag effect="plain">{{ requirementLabel(scope.row.meta?.requirementLevel||scope.row.meta?.relationLevel) }}</el-tag></template></el-table-column><el-table-column label="应用位置 / 对象"><template #default="scope">{{ scope.row.meta?.condition||'场景范围内' }}</template></el-table-column></el-table></section>
          <section v-if="activeTab==='overview' || activeTab==='process'" class="content-section"><div class="section-head"><div><h2>系统业务流程</h2><p>从目标进入到预警联动的节点闭环。</p></div></div><div class="process-flow"><template v-for="(item,index) in record.process" :key="item.id||item.nodeTitle"><article><span>{{ index+1 }}</span><strong>{{ item.nodeTitle }}</strong><small>{{ item.nodeDescription }}</small></article><b v-if="index<record.process.length-1">→</b></template></div></section>
          <section v-if="activeTab==='overview' || activeTab==='products' || activeTab==='solutions'" class="recommendations"><article v-if="activeTab!=='solutions'"><h2>推荐产品</h2><div><button v-for="item in relationGroups.products" :key="item.id" @click="emit('openRelation',item)"><img src="/assets/product-terminal.png" :alt="item.name"><strong>{{ item.name }}</strong><span>{{ item.meta?.purpose||'查看产品' }}</span></button></div></article><article v-if="activeTab!=='products'"><h2>标准方案</h2><div><button v-for="item in relationGroups.solutions" :key="item.id" @click="emit('openRelation',item)"><small>{{ item.meta?.solutionLevel||'标准型' }}</small><strong>{{ item.name }}</strong><span>{{ item.meta?.recommendationReason||'查看方案配置' }}</span></button></div></article></section>
        </template>

        <template v-else>
          <div v-if="activeTab==='overview' || activeTab==='conditions'" class="solution-intro"><article><h2>建设目标</h2><p>{{ record.targetDescription||record.summary }}</p></article><article><h2>适用条件</h2><p>{{ record.coverageScope||'适用条件待完善' }}</p></article></div>
          <section v-if="activeTab==='overview' || activeTab==='architecture'" class="content-section"><div class="section-head"><div><h2>系统架构与真实组成对象</h2><p>每一层引用产品、软件、算法或模型能力对象。</p></div><span>{{ architectureGroups.length }} 层 · {{ record.architecture?.length||0 }} 对象</span></div><div class="architecture-flow"><template v-for="(group,index) in architectureGroups" :key="group.layer"><article><small>{{ String(index+1).padStart(2,'0') }}</small><h3>{{ group.layer }}</h3><div><span v-for="item in group.items" :key="item.id"><b>{{ item.name }}</b>{{ item.description }}</span></div></article><b v-if="index<architectureGroups.length-1">→</b></template></div><el-empty v-if="!architectureGroups.length" description="暂无架构节点"/></section>
          <RelationPanel v-if="activeTab==='composition'" :groups="relationGroups" :can-manage="canManage" @open="emit('openRelation',$event)" @relate="emit('relate')"/>
          <section v-if="activeTab==='overview' || activeTab==='coverage'" class="content-section"><div class="section-head"><div><h2>能力覆盖</h2><p>明确覆盖状态、实现方式与关联对象。</p></div></div><el-table :data="record.capabilityCoverage||[]"><el-table-column prop="capabilityName" label="能力名称"/><el-table-column label="覆盖状态"><template #default="scope"><el-tag :type="scope.row.status==='COVERED'?'success':'info'" effect="plain">{{ coverageLabel(scope.row.status) }}</el-tag></template></el-table-column><el-table-column prop="implementation" label="实现方式"/><el-table-column label="关联对象"><template #default="scope">{{ scope.row.relationObjects?.join('、')||'-' }}</template></el-table-column><el-table-column prop="notes" label="备注"/></el-table></section>
          <section v-if="activeTab==='bom'" class="content-section"><div class="section-head"><div><h2>标准BOM</h2><p>引用产品中心真实产品与主型号。</p></div><el-button v-if="canManage" :icon="Edit" @click="emit('editBom')">编辑BOM</el-button></div><el-table :data="record.bom?.items||[]"><el-table-column prop="product" label="产品"/><el-table-column prop="primaryModel" label="型号"/><el-table-column prop="quantity" label="数量" width="70"/><el-table-column prop="unit" label="单位" width="70"/><el-table-column prop="purpose" label="用途"/><el-table-column label="要求"><template #default="scope">{{ requirementLabel(scope.row.requirementLevel) }}</template></el-table-column><el-table-column prop="recommendationReason" label="推荐理由"/><el-table-column v-if="showPrice" label="单价"><template #default="scope">{{ scope.row.unitPrice==null?'-':'¥ '+Number(scope.row.unitPrice).toLocaleString() }}</template></el-table-column><el-table-column v-if="showPrice" label="小计"><template #default="scope">{{ scope.row.subtotal==null?'-':'¥ '+Number(scope.row.subtotal).toLocaleString() }}</template></el-table-column></el-table><div v-if="showPrice" class="bom-total">产品参考总价 <strong>¥ {{ Number(record.bom?.productReferenceTotal||0).toLocaleString() }}</strong></div></section>
        </template>
        <section v-if="activeTab==='commercial'" class="content-section"><div class="section-head"><div><h2>{{centerKey==='algorithms'?'授权与商务规则':'物料与商务规则'}}</h2><p>字段来自正式配单材料；敏感价格仅向 PRICE_VIEW 返回。</p></div><el-button v-if="canManage" :icon="Edit" @click="beginEdit">原位编辑</el-button></div><el-descriptions v-if="record.commercial" :column="2" border><el-descriptions-item label="物料代码">{{record.commercial.materialCode||'-'}}</el-descriptions-item><el-descriptions-item label="单位 / 授权单位">{{record.commercial.licenseUnit||record.commercial.unit||'-'}}</el-descriptions-item><el-descriptions-item label="商业状态">{{statusLabel(record.commercial.commercialStatus)}}</el-descriptions-item><el-descriptions-item label="默认质保">{{record.commercial.warrantyMonths}} 个月</el-descriptions-item><el-descriptions-item v-if="centerKey==='algorithms'" label="基础路数">{{record.commercial.includedQuantity??'-'}}</el-descriptions-item><el-descriptions-item label="适用场景">{{record.commercial.applicableScenes?.join('、')||'-'}}</el-descriptions-item><el-descriptions-item v-if="showPrice" label="代理单价">{{record.commercial.agentPrice==null?'-':'¥ '+Number(record.commercial.agentPrice).toLocaleString()}}</el-descriptions-item><el-descriptions-item v-if="showPrice" label="销售单价">{{record.commercial.salePrice==null?'-':'¥ '+Number(record.commercial.salePrice).toLocaleString()}}</el-descriptions-item><el-descriptions-item v-if="showPrice&&centerKey==='algorithms'" label="超额单价">{{record.commercial.overageUnitPrice==null?'-':'¥ '+Number(record.commercial.overageUnitPrice).toLocaleString()}}</el-descriptions-item><el-descriptions-item label="交付 / 延保">{{record.commercial.deliveryMethod||record.commercial.extendedWarrantyRule||'-'}}</el-descriptions-item><el-descriptions-item label="销售备注" :span="2">{{record.commercial.salesNotes||'-'}}</el-descriptions-item></el-descriptions><el-empty v-else description="暂无商务资料"/></section>
        <section v-if="activeTab==='documents'" class="content-section"><DocumentAssets :center-type="centerKey" :center-id="record.id" :can-manage="canManage" :can-download="canDownload"/></section>
      </main>
    </template>
  </section>
</template>

